package com.herbharvestguard;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("herbHarvestGuard")
public interface HerbHarvestGuardConfig extends Config
{
    @ConfigItem(
        keyName = "requireMagicSecateurs",
        name = "Require Magic secateurs",
        description = "Block herb harvesting unless Magic secateurs are equipped or in your inventory",
        position = 0
    )
    default boolean requireMagicSecateurs()
    {
        return true;
    }

    @ConfigItem(
        keyName = "requireFarmingCape",
        name = "Require Farming cape",
        description = "Block herb harvesting unless a Farming cape is equipped",
        position = 1
    )
    default boolean requireFarmingCape()
    {
        return false;
    }

    @ConfigItem(
        keyName = "showChatWarning",
        name = "Show chat warning",
        description = "Show a chat message when a harvest is blocked",
        position = 2
    )
    default boolean showChatWarning()
    {
        return true;
    }
}

package com.herbharvestguard;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Herb Harvest Guard",
    description = "Prevents harvesting herbs without selected yield-boosting items",
    tags = {"farming", "herbs", "secateurs", "cape", "yield"},
    enabledByDefault = true,
    hidden = false
)
public class HerbHarvestGuardPlugin extends Plugin
{
    private static final int MAGIC_SECATEURS = 7409;
    private static final int FARMING_CAPE = 9810;
    private static final int FARMING_CAPE_T = 9811;

    private static final Set<String> HERB_NAMES = new HashSet<>(Arrays.asList(
        "guam", "marrentill", "tarromin", "harralander", "ranarr",
        "toadflax", "irit", "avantoe", "kwuarm", "snapdragon",
        "cadantine", "lantadyme", "dwarf weed", "torstol"
    ));

    @Inject private Client client;
    @Inject private HerbHarvestGuardConfig config;

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!isHerbPick(event.getOption(), event.getTarget())) return;
        MissingRequirements missing = getMissingRequirements();
        if (!missing.anyMissing()) return;

        // Rename only. Keeping the original game action type preserves
        // the exact priority/order of the normal Pick interaction.
        event.getMenuEntry()
            .setOption("Missing yield boost");
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        String option = event.getMenuOption();

        boolean herbInteraction =
            isHerbPick(option, event.getMenuTarget())
            || ("Missing yield boost".equalsIgnoreCase(option)
                && isHerbTarget(event.getMenuTarget()));

        if (!herbInteraction) return;

        MissingRequirements missing = getMissingRequirements();
        if (!missing.anyMissing()) return;

        // Hard stop: do not allow the underlying harvest action to reach the game.
        event.consume();
        showBlockedMessage(missing);
    }

    private boolean isHerbPick(String option, String target)
    {
        return "Pick".equalsIgnoreCase(option) && isHerbTarget(target);
    }

    private boolean isHerbTarget(String target)
    {
        String clean = Text.removeTags(target).trim().toLowerCase();
        if (clean.equals("herbs")) return true;

        for (String herb : HERB_NAMES)
        {
            if (clean.equals(herb) || clean.contains(herb)) return true;
        }

        return false;
    }

    private MissingRequirements getMissingRequirements()
    {
        return new MissingRequirements(
            config.requireMagicSecateurs() && !hasMagicSecateurs(),
            config.requireFarmingCape() && !hasFarmingCapeEquipped()
        );
    }

    private boolean hasMagicSecateurs()
    {
        return contains(InventoryID.INVENTORY, MAGIC_SECATEURS)
            || contains(InventoryID.EQUIPMENT, MAGIC_SECATEURS);
    }

    private boolean hasFarmingCapeEquipped()
    {
        return contains(InventoryID.EQUIPMENT, FARMING_CAPE)
            || contains(InventoryID.EQUIPMENT, FARMING_CAPE_T);
    }

    private boolean contains(InventoryID inventoryID, int itemId)
    {
        ItemContainer container = client.getItemContainer(inventoryID);
        return container != null && container.contains(itemId);
    }

    private void showBlockedMessage(MissingRequirements missing)
    {
        if (!config.showChatWarning() || !missing.anyMissing()) return;
        String requirementText;
        if (missing.magicSecateurs && missing.farmingCape)
            requirementText = "Magic secateurs and a Farming cape";
        else if (missing.magicSecateurs)
            requirementText = "Magic secateurs";
        else
            requirementText = "a Farming cape";

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
            "Herb Harvest Guard won't let you pick herbs without " + requirementText + ".", null);
    }

    @Provides
    HerbHarvestGuardConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(HerbHarvestGuardConfig.class);
    }

    private static final class MissingRequirements
    {
        private final boolean magicSecateurs;
        private final boolean farmingCape;
        private MissingRequirements(boolean magicSecateurs, boolean farmingCape)
        {
            this.magicSecateurs = magicSecateurs;
            this.farmingCape = farmingCape;
        }
        private boolean anyMissing() { return magicSecateurs || farmingCape; }
    }
}

package com.herbharvestguard;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HerbHarvestGuardPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(HerbHarvestGuardPlugin.class);
        RuneLite.main(args);
    }
}
